#include <X11/Xlib.h>
#include <stdio.h>
int main(void){Display*d=XOpenDisplay(0);Window w;GC gc;XEvent e;XFontStruct*font;char**names;int fonts=0;static const XChar2b wide[]={{0x65,0xe5},{0x67,0x2c},{0x8a,0x9e}};if(!d){fprintf(stderr,"xzed-demo: cannot open display\n");return 1;}names=XListFonts(d,"*",16,&fonts);if(!names||fonts!=1){fprintf(stderr,"xzed-demo: font enumeration failed\n");return 1;}XFreeFontNames(names);font=XLoadQueryFont(d,"zed-unicode");if(!font){fprintf(stderr,"xzed-demo: font load failed\n");return 1;}w=XCreateSimpleWindow(d,DefaultRootWindow(d),80,70,400,240,1,WhitePixel(d,0),0x406080);gc=XCreateGC(d,w,0,0);XSetFont(d,gc,font->fid);XSelectInput(d,w,ExposureMask|KeyPressMask|ButtonPressMask|PointerMotionMask);XMapWindow(d,w);for(;;){if(XNextEvent(d,&e)<0)break;if(e.type==Expose){int i;XSetForeground(d,gc,WhitePixel(d,0));for(i=0;i<5;i++)XFillRectangle(d,w,gc,20+i*70,25,50,120);XDrawString(d,w,gc,20,175,"zedBSD Unicode",14);XDrawString16(d,w,gc,20,205,wide,3);}}XFreeGC(d,gc);XFreeFont(d,font);XDestroyWindow(d,w);XCloseDisplay(d);return 0;}
